            for x, y in {(a, b), (b, a)}:
                if fits(r, c, x, y):
                    used[i] = True
                    fill(r, c, x, y, True)
                    if dfs(pos):
                        return True
                    fill(r, c, x, y, False)
                    used[i] = False
        return False

    return dfs(0)
